const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const newYork = ee.Geometry.Point(-74.0060, 40.7128); // New York City coordinates

  const dateJan29 = '2019-01-29';
  const dateFeb05 = '2019-02-05';

  // Define scale for reduceRegion, ERA5-Land resolution is ~10km (0.1 degree)
  const scale = 10000; // Use a scale similar to data resolution for general analysis

  // 2. Data Acquisition & Check
  const era5Land = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .select('temperature_2m'); // Select 2-meter air temperature band

  // Get average temperature for January 29, 2019
  const jan29Collection = era5Land.filterDate(dateJan29, ee.Date(dateJan29).advance(1, 'day'));
  if (jan29Collection.size().getInfo() === 0) {
    console.log("No ERA5-Land data found for January 29, 2019.");
    console.log("C1");
    return;
  }
  const jan29TempK = jan29Collection.mean();

  // Get average temperature for February 5, 2019
  const feb05Collection = era5Land.filterDate(dateFeb05, ee.Date(dateFeb05).advance(1, 'day'));
  if (feb05Collection.size().getInfo() === 0) {
    console.log("No ERA5-Land data found for February 5, 2019.");
    console.log("C1");
    return;
  }
  const feb05TempK = feb05Collection.mean();

  // 3. Processing and 4. Calculation
  // Reduce regions to get temperature values in Kelvin
  const jan29TempKelvin = jan29TempK.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: newYork,
    scale: scale,
    maxPixels: 1e9,
  }).get('temperature_2m').getInfo();

  const feb05TempKelvin = feb05TempK.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: newYork,
    scale: scale,
    maxPixels: 1e9,
  }).get('temperature_2m').getInfo();

  // 5. Validation & Final Answer
  if (jan29TempKelvin === null || feb05TempKelvin === null ||
      isNaN(jan29TempKelvin) || isNaN(feb05TempKelvin)) {
    console.log("Failed to retrieve temperature values (None/NaN).");
    console.log("C3");
    return;
  }

  // Convert Kelvin to Celsius (K - 273.15 = C)
  const jan29TempC = jan29TempKelvin - 273.15;
  const feb05TempC = feb05TempKelvin - 273.15;

  const temperatureDifference = Math.abs(jan29TempC - feb05TempC);

  console.log(`Jan 29, 2019 Avg Temp (C): ${jan29TempC.toFixed(2)}`);
  console.log(`Feb 05, 2019 Avg Temp (C): ${feb05TempC.toFixed(2)}`);
  console.log(`Absolute Temperature Difference (C): ${temperatureDifference.toFixed(2)}`);

  if (temperatureDifference >= 24) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
